 * @param  string  $value
 * @return string
 */
protected function storeUncompiledBlocks($value)
{
    if (str_contains($value, '@verbatim')) {
        $value = $this->storeVerbatimBlocks($value);
    }

    if (str_contains($value, '@php')) {
        $value = $this->storePhpBlocks($value);
    }

    return $value;
}

